    static Stream<Arguments> utcDateCases() {
        return Stream.of(
                Arguments.of("2026-07-01T23:30:00Z", "2026-07-08T00:10:00Z", 7),
                Arguments.of("2026-07-01T00:00:00Z", "2026-07-09T23:59:59Z", 8)
        );
    }
}


